// Only place that talks to the backend. Bindings are generated — never hand-write them.
// Until `wails3 generate bindings` has run, these fall back to browser-safe stubs so the
// frontend still typechecks and runs in a plain browser.
import type { Flow } from "@shared/lib/types"

type RunEvent =
  | { type: "run.started"; runId: string }
  | { type: "node.started"; nodeId: string }
  | { type: "node.finished"; nodeId: string; status: string }
  | { type: "run.finished"; status: string }

const inWails = typeof window !== "undefined" && "go" in window

// generated by: wails3 generate bindings -ts -d frontend/bindings
const BINDINGS = "@bindings/flow/api"

async function bindings(): Promise<typeof import("@bindings/flow/api")> {
  return import(/* @vite-ignore */ BINDINGS) as Promise<typeof import("@bindings/flow/api")>
}

export const api = {
  async getFlow(id: string): Promise<Flow | null> {
    if (!inWails) return null
    const { GetFlow } = await bindings()
    return (await GetFlow(id)) as Flow | null
  },

  async saveFlow(f: Flow): Promise<void> {
    if (!inWails) return
    const { SaveFlow } = await bindings()
    await SaveFlow(f)
  },

  async runFlow(id: string): Promise<string> {
    if (!inWails) return ""
    const { StartRun } = await bindings()
    return StartRun(id)
  },

  onRunEvent(cb: (e: RunEvent) => void): () => void {
    if (!inWails) return () => {}
    let off: (() => void) | undefined
    import("@wailsio/runtime").then((rt) => {
      const names = ["run.started", "node.started", "node.finished", "run.finished"] as const
      const unsubs = names.map((n) =>
        rt.Events.On(n, (e: { data: unknown }) => cb({ type: n, ...(e.data as object) } as RunEvent)),
      )
      off = () => unsubs.forEach((u) => u())
    })
    return () => off?.()
  },
}
